// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GameProfile) predicate.GameProfile {
	return predicate.GameProfile(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GameProfile) predicate.GameProfile {
	return predicate.GameProfile(sql.NotPredicates(p))
}
